import json,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent;D=P/'stress_cpu_01';A=P.parent/'rte_recycling_20261110_dot_v1/confirmation_cpu_01/settings.json'
s=json.loads((D/'settings.json').read_text());a=json.loads(A.read_text());rows=json.loads((D/'rows.json').read_text());b=json.loads((D/'batches.json').read_text());assert s['complete']
for f,h in s['source_hashes'].items():assert hashlib.sha256((P/f).read_bytes()).hexdigest()==h
for key in ['source_ids','grid','L','g','prefix','tangent_cut','inner_tolerance','inner_maxiter','outer_tolerance','outer_maxiter','rhs_sha256']:assert s[key]==a[key],key
assert s['production_hashes']==s['production_hashes_after']==a['production_hashes']
assert s['orders']==[['compact4_inject','exact8_inner']]
assert s['inclusion_amplitude']==6 and s['baseline_inclusion_amplitude']==3 and s['material_identity']['amplitude3_byte_equal_original']
assert s['material_identity']['stress_total_sha256']!=s['material_identity']['baseline_total_sha256']
x={v['method']:v for v in b};c=x['compact4_inject'];e=x['exact8_inner'];er=[v for r in rows if r['method']=='exact8_inner' for v in r['inner_records']]
d=dict(complete=True,scope=s['scope'],frozen_settings_verified=True,source_arrays_unchanged=True,production_hashes_unchanged=True,material_identity=s['material_identity'],methods=x,gain_percent=100*(1-e['batch_complete_seconds']/c['batch_complete_seconds']),observed_wall_gain_percent=100*(1-e['observed_batch_wall_seconds']/c['observed_batch_wall_seconds']),extra_setup_seconds=e['setup_seconds']-c['setup_seconds'],online_savings_seconds=c['online_four_rhs_seconds']-e['online_four_rhs_seconds'],attempts=len(rows),failures=sum(not r['accepted'] for r in rows),inner_calls=[v['iterations'] for v in er],inner_residuals=[v['true_residual'] for v in er],inner_failures=sum(v['failed'] for v in er),max_original_residual=max(r['true_residual'] for r in rows),max_evaluated_bound=max(r['evaluated_relative_bound'] for r in rows),max_field_difference=max(r['relative_field_difference'] for r in rows),reference_attempts=len(json.loads((D/'reference_checks.json').read_text())),reference_research_seconds=s['reference_research_seconds'],wall_seconds=s['wall_seconds'],source_hashes=s['source_hashes'])
(P/'analysis.json').write_text(json.dumps(d,indent=2)+'\n')
lines=['# B: predetermined inclusion-strength perturbation','','## What was frozen','','Only the inclusion amplitude changed from3 to6. Position(.34,.60), width.08, layer profile, N128/L12/g.65, scattering scale10/3, original4 RHS arrays/order and every numerical threshold match the immutable A confirmation. The amplitude3 constructor was first verified byte-for-byte against the original. One pair, predeclared compact4 then exact8_inner, CPU0/one thread/noGPU; each method rebuilds and pays all setup.','','## Result','','| Method | Fresh setup seconds | Four-RHS online seconds | Complete seconds | Observed batch wall seconds | Outer TSA64 calls |','|---|---:|---:|---:|---:|---|']
for name,v in x.items():lines.append(f"| {name} | {v['setup_seconds']:.3f} | {v['online_four_rhs_seconds']:.3f} | {v['batch_complete_seconds']:.3f} | {v['observed_batch_wall_seconds']:.3f} | {v['calls']} |")
lines+=['',f"Observed phase-summed batch gain {d['gain_percent']:.2f}%; directly observed whole-batch gain {d['observed_wall_gain_percent']:.2f}%. Extra exact setup {d['extra_setup_seconds']:.3f}s versus online savings {d['online_savings_seconds']:.3f}s. These are one predeclared pair, not repeated timing or material generalization.",'',f"Exact inner calls: {d['inner_calls']}; true inner residuals: {d['inner_residuals']}; inner failures: {d['inner_failures']}. Budget stayed tolerance1e-4/max8; there was no tuning or replacement material after the outcome.",'',f"All {d['attempts']} candidate outer attempts: {d['failures']} failures. Maximum original residual {d['max_original_residual']:.6g}, evaluated relative bound {d['max_evaluated_bound']:.6g}, field difference {d['max_field_difference']:.6g}. Source hashes, frozen settings and production hashes verified unchanged.",'',f"Four ordinary native accepted-reference solves were used only for paired field checks, separately costing {d['reference_research_seconds']:.3f}s. Total stress-script main wall {d['wall_seconds']:.3f}s. No accurate new teachers or training.",'','## Bounded interpretation','','This result tests only the predetermined doubled-inclusion perturbation. It is not evidence for arbitrary materials, sources, higher grids or GPU acceleration. Preserve any failures and do not adjust the eight-step budget to rescue this test. GPU economics remain a separate coordinated gate.','','## Evidence','','stress_cpu_01/settings.json: material/source hashes, frozen parameters and source code hashes. rows.json: all residuals, checks, inner/outer calls and per-source times. batches.json: paid phase costs and observed whole-batch wall. reference_checks.json: ordinary reference solves. analyze_stress.py reproduces this report and verifies equality with the immutable A settings.','']
(P/'STRESS_REPORT.md').write_text('\n'.join(lines));print(json.dumps(d,indent=2))
